package com.academy.mudogroupware.global.infrastructure.security.websocket;
import com.academy.mudogroupware.global.domain.auth.AuthException; import com.academy.mudogroupware.global.infrastructure.security.jwt.JwtTokenProvider; import com.academy.mudogroupware.global.presentation.security.JwtAuthenticationConverter; import lombok.RequiredArgsConstructor; import org.springframework.messaging.*; import org.springframework.messaging.simp.stomp.*; import org.springframework.messaging.support.*; import org.springframework.stereotype.Component; import org.springframework.util.StringUtils; import java.util.Map;
@Component @RequiredArgsConstructor public class JwtChannelInterceptor implements ChannelInterceptor { private final JwtTokenProvider provider; private final JwtAuthenticationConverter converter; public Message<?> preSend(Message<?> m,MessageChannel c){StompHeaderAccessor a=StompHeaderAccessor.wrap(m);if(StompCommand.CONNECT.equals(a.getCommand())){Map<String,Object>s=a.getSessionAttributes();String t=s==null?null:(String)s.get("accessToken");if(!StringUtils.hasText(t))throw new MessageDeliveryException(m,"Access token cookie missing");try{a.setUser(converter.toAuthentication(provider.parseAccessToken(t)));return MessageBuilder.createMessage(m.getPayload(),a.getMessageHeaders());}catch(AuthException e){throw new MessageDeliveryException(m,"Invalid JWT token",e);}}return m;} }
